import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { gradeOn, type Person } from '../people/people';
import { countsAsOf, holdsOf, type Claim } from '../claims/claims';
import { chargedOf, sumDue, type Rate } from '../rates/rates';
import type { Settings } from '../roles/roles';

/** A sheet's period as the store holds it: its name (unique on the sheet) and its from and to date
 *  (YYYY-MM-DD), inclusive. No two periods overlap. A closed period keeps the due-total fixed when it was closed
 *  (`closedTotal`, null while open), and each person's fixed then (`personTotals`, by person id; empty while
 *  open), until a steward reopens it. */
export type Period = {
  id: number; name: string; from: string; to: string; closed: boolean; closedTotal: string | null;
  personTotals: Record<string, string>;
};

export const periodsQueryKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;

export const periodsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/periods`;

export const periodClosePath = (sheetId: string, periodId: number) => `${periodsPath(sheetId)}/${periodId}/close`;

export const periodReopenPath = (sheetId: string, periodId: number) => `${periodsPath(sheetId)}/${periodId}/reopen`;

/** The sheet's periods, by from-date. */
export function usePeriods() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: periodsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Period[]>(periodsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The period whose dates contain a date (YYYY-MM-DD), or undefined for none. */
export function periodOn(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => p.from <= date && date <= p.to);
}

/** A period's due-total: the dues (with any late charge, as shown now) of the claims whose date falls in it that counted
 *  by the status they had at the end of its last day (not a person's unbound OPEN ones dated within a hold of theirs), added up, skipping n/a; for a closed period, the one fixed when it was closed. */
export function periodDue(period: Period, people: Person[] | undefined, claims: Claim[], rates: Rate[] | undefined,
  settings: Settings | undefined, today: string | undefined): string {
  if (period.closedTotal !== null) return period.closedTotal;
  const personOf = new Map((people ?? []).map((p) => [p.id, p]));
  const held = holdsOf(people);
  return sumDue(claims
    .filter((c) => countsAsOf(c, held, today, period.to) && personOf.has(c.personId) && periodOn([period], c.date))
    .map((c) => chargedOf(c, rates, gradeOn(personOf.get(c.personId)!, c.date), settings, today)));
}

/** A person's due-total for a period: the dues (with any late charge, as shown now) of their claims whose date falls in
 *  it that counted by the status they had at the end of its last day
 *  (not their unbound OPEN ones dated within a hold of theirs), added up, skipping n/a; for a closed period, the one
 *  fixed when it was closed — 0.00 for a person added since. */
export function personPeriodDue(period: Period, person: Person, people: Person[] | undefined, claims: Claim[],
  rates: Rate[] | undefined, settings: Settings | undefined, today: string | undefined): string {
  if (period.closed) return period.personTotals?.[String(person.id)] ?? '0.00';
  const held = holdsOf(people);
  return sumDue(claims
    .filter((c) => c.personId === person.id && countsAsOf(c, held, today, period.to) && periodOn([period], c.date))
    .map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { usePeople } from '../people/people';
import { useClaims } from '../claims/claims';
import { useRates } from '../rates/rates';
import { useSettings } from '../roles/roles';
import { periodClosePath, periodDue, periodReopenPath, periodsPath, periodsQueryKey, usePeriods, type Period } from './periods';

// The sheet's periods, each with its due-total — the dues (with any late charge) of the counted claims whose date falls in it (not a person's unbound OPEN ones dated within a hold of theirs),
// added up, skipping n/a; for a closed period, the one fixed when it was closed — whether it is closed, the
// buttons that close and reopen it, and the form that adds one.
function Periods() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const periods = usePeriods();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const settings = useSettings();
  const today = useSheetToday();
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { name: string; from: string; to: string }) =>
      postJson<Period>(periodsPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsQueryKey(sheet ?? '') });
      setName('');
      setFrom('');
      setTo('');
    },
  });
  const submit = useSubmitOnce(add);

  if (!user || !sheet) return null;
  const dueTotal = (period: Period) =>
    periodDue(period, people.data, claims.data ?? [], rates.data, settings.data, today);
  return (
    <section data-testid="periods">
      <h2>Periods</h2>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.id} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{dueTotal(p)}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                <PeriodActions key={`${sheet}:${p.id}`} sheet={sheet} period={p} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ name, from, to });
        }}
      >
        <input
          data-testid="period-form-name"
          placeholder="Name"
          value={name}
          onChange={(e) => { setName(e.target.value); add.reset(); }}
        />
        <input
          data-testid="period-form-from"
          placeholder="From (YYYY-MM-DD)"
          value={from}
          onChange={(e) => { setFrom(e.target.value); add.reset(); }}
        />
        <input
          data-testid="period-form-to"
          placeholder="To (YYYY-MM-DD)"
          value={to}
          onChange={(e) => { setTo(e.target.value); add.reset(); }}
        />
        <button type="submit" data-testid="period-form-submit" disabled={add.isPending}>
          Add period
        </button>
        {add.isError && (
          <span data-testid="period-form-error">A period needs a name the sheet does not have yet, and calendar from and to dates, the to-date on or after the from-date, not overlapping another period.</span>
        )}
      </form>
    </section>
  );
}

// The buttons that close and reopen a period. Closing one already closed, or reopening one not closed, or either by
// a role the permission matrix does not allow (by the standing rule, reopening by anyone but a steward), is refused by the server and shows the period's error, which goes as soon as the next
// action on the row is taken.
function PeriodActions({ sheet, period }: { sheet: string; period: Period }) {
  const [user] = useCurrentUser();
  const queryClient = useQueryClient();
  const onSuccess = () => queryClient.invalidateQueries({ queryKey: ['sheet', sheet] });
  const close = useMutation({
    mutationFn: () => putJson<Period>(periodClosePath(sheet, period.id), undefined, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsQueryKey(sheet) }),
  });
  const reopen = useMutation({
    mutationFn: () => putJson<Period>(periodReopenPath(sheet, period.id), undefined, user),
    onSuccess,
  });
  const submitClose = useSubmitOnce(close);
  const submitReopen = useSubmitOnce(reopen);
  const pending = close.isPending || reopen.isPending;
  return (
    <>
      <button type="button" data-testid="period-close" disabled={pending}
        onClick={() => { reopen.reset(); submitClose(); }}>
        Close
      </button>
      <button type="button" data-testid="period-reopen" disabled={pending}
        onClick={() => { close.reset(); submitReopen(); }}>
        Reopen
      </button>
      {close.isError && <span data-testid="period-error">This period cannot be closed: it is already closed, or your role is not allowed to close one.</span>}
      {reopen.isError && <span data-testid="period-error">This period cannot be reopened: it is not closed, or your role is not allowed to reopen one.</span>}
    </>
  );
}

export const contribution = HomeMain.fill({ order: 6, Component: Periods });

